(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let client,session=null,uid=null,revision=0,pending=null,timer=null,writing=false,conflict=false,notify=()=>{},generation=0,remoteState=null;
const account={ready:false,configured:false,error:'',status:'',recovery:false,emailConfirmationRequired:true,loadId:0,get signedIn(){return !!session},get email(){return session?.user.email||''},get state(){return remoteState}};
const status=s=>{account.status=s;const e=document.querySelector('#cloud-status');if(e)e.textContent=s;const detail=document.querySelector('#account-save-status');if(detail)detail.textContent=s};
function cleanState(state){if(!state||typeof state!=='object'||Array.isArray(state))return {};return JSON.parse(JSON.stringify(state))}
async function load(next,event){session=next;if(event==='PASSWORD_RECOVERY')account.recovery=true;const nextUid=next?.user.id||null;if(account.ready&&nextUid===uid){if(event==='PASSWORD_RECOVERY')notify();return}const gen=++generation;uid=nextUid;pending=null;revision=0;conflict=false;remoteState=null;account.ready=false;account.error='';notify();if(uid){const r=await client.from('bora_progress').select('state,revision').eq('user_id',uid).maybeSingle();if(gen!==generation)return;if(r.error){account.error='Не удалось загрузить прогресс. Повтори загрузку; изменения пока недоступны.'}else{remoteState=cleanState(r.data?.state);revision=r.data?.revision||0}}if(gen!==generation)return;account.ready=true;account.loadId++;status(uid?'Прогресс загружен из базы':'Войди, чтобы сохранить прогресс');notify()}
account.init=async onChange=>{notify=onChange;try{const r=await fetch('/api/config',{cache:'no-store'}),config=await r.json();if(!config.supabaseUrl||!config.supabaseKey){account.ready=true;account.error='Регистрация пока настраивается.';notify();return}client=window.BoraCreateSupabaseClient(config.supabaseUrl,config.supabaseKey,{auth:{storageKey:'bora.auth.session',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'}});account.liveEnabled=config.live?.enabled===true;account.speechProvider=config.speechProvider==='azure'?'azure':'edge';account.emailConfirmationRequired=config.emailConfirmationRequired!==false;account.configured=true;let initializing=true;client.auth.onAuthStateChange((event,next)=>{if(event==='PASSWORD_RECOVERY')account.recovery=true;if(!initializing)setTimeout(()=>load(next,event),0)});const {data,error}=await client.auth.getSession();if(error)throw error;await load(data.session);initializing=false}catch{account.ready=true;account.error='Не удалось подключиться к базе. Повтори загрузку страницы.';notify()}};
account.queue=state=>{if(!uid||account.error)return;pending=cleanState(state);status(conflict?'Прогресс изменён на другом устройстве. Открой аккаунт и загрузи актуальную версию.':'Есть несохранённые изменения…');clearTimeout(timer);timer=setTimeout(flush,600)};
async function flush(){if(writing||!pending||!uid||conflict)return;writing=true;const snapshot=pending,owner=uid,gen=generation;pending=null;status('Сохраняю в базу…');try{let r;if(revision===0)r=await client.from('bora_progress').insert({user_id:owner,state:snapshot}).select('revision').single();else r=await client.from('bora_progress').update({state:snapshot}).eq('user_id',owner).eq('revision',revision).select('revision').maybeSingle();if(gen!==generation)return;if(r.error||!r.data){if(r.error?.code==='23505'||!r.error){conflict=true;pending=pending||snapshot;status('Прогресс изменён на другом устройстве. Открой аккаунт и загрузи актуальную версию.');return}throw r.error}revision=r.data.revision;remoteState=snapshot;status(pending?'Сохраняю новые изменения…':'Сохранено в базе ✓')}catch{if(gen===generation){pending=pending||snapshot;status('Не сохранено: проверь интернет. Повторить можно в аккаунте.')}}finally{writing=false;if(pending&&!conflict&&gen===generation)clearTimeout(timer),timer=setTimeout(()=>{if(navigator.onLine)flush()},10000)}}
account.flush=flush;account.accessToken=async()=>{const r=await client.auth.getSession();if(r.error||!r.data.session)throw Error('Войди в аккаунт снова.');return r.data.session.access_token};
account.page=()=>{if(!account.ready)return '<div class="narrow panel"><h1>Загружаю аккаунт…</h1></div>';if(!account.configured)return `<div class="narrow panel"><h1>Подключаем аккаунты</h1><p>${esc(account.error)}</p><a href="#courses">Открыть программы</a></div>`;if(session&&!account.recovery)return `<div class="narrow panel"><div class="eyebrow">Твой аккаунт</div><h1>Прогресс с тобой.</h1><p>${esc(account.email)}</p><p id="account-save-status">${esc(account.status)}</p>${account.error?`<div class="notice">${esc(account.error)}</div>`:''}<div class="row"><button class="btn" id="cloud-retry">Повторить сохранение</button><button class="btn alt" id="cloud-reload">Загрузить из базы</button><button class="btn alt" id="logout">Выйти</button></div><h3 style="margin-top:25px">Прогресс из старого браузера</h3><p class="small">Если ты занимался до регистрации, можешь перенести один из прежних профилей в этот аккаунт. Текущий прогресс в базе не будет заменён автоматически.</p><button class="btn alt" id="legacy-show">Найти прежние профили</button><div id="legacy-options"></div><p id="auth-feedback" role="status" aria-live="polite"></p></div>`;
return `<div class="narrow panel"><div class="eyebrow">Bora · личный кабинет</div><h1>${account.recovery?'Новый пароль':'Учись с любого устройства.'}</h1><p>Войди по email и паролю — результаты уроков, заметки и история помощника сохранятся в базе твоего аккаунта.</p><form id="auth-form">${account.recovery?'':'<label>Email<input name="email" type="email" autocomplete="email" required maxlength="254"></label>'}<label>Пароль<input name="password" type="password" autocomplete="${account.recovery?'new-password':'current-password'}" minlength="8" maxlength="128" required></label><div class="row"><button class="btn" type="submit">${account.recovery?'Сохранить пароль':'Войти'}</button>${account.recovery?'':'<button class="btn alt" type="button" id="register">Зарегистрироваться</button>'}</div></form>${account.recovery?'':account.emailConfirmationRequired?'<button class="btn alt" style="margin-top:16px" id="password-reset">Забыли пароль?</button><p class="small">Подтверди email по ссылке из письма. Пароль — минимум 8 символов.</p>':'<p class="small">Личный пилот: регистрация сразу, без письма подтверждения. Пароль — минимум 8 символов. Сохрани его: восстановление по почте пока недоступно.</p>'}<p id="auth-feedback" role="status" aria-live="polite"></p></div>`};
account.bind=(getState,applyState)=>{const $=s=>document.querySelector(s),msg=s=>{if($('#auth-feedback'))$('#auth-feedback').textContent=s};let busy=false;const run=async action=>{if(busy)return;busy=true;msg('Подожди немного…');try{await action()}catch(e){msg(e.message||'Не удалось выполнить действие. Попробуй ещё раз.')}finally{busy=false}};
const form=$('#auth-form'),redirect=location.origin+'/';const fields=()=>{if(!form.reportValidity())return null;const d=new FormData(form);return {email:String(d.get('email')||'').trim(),password:String(d.get('password')||'')}};
if(form)form.onsubmit=e=>{e.preventDefault();const f=fields();if(!f)return;run(async()=>{if(account.recovery){const r=await client.auth.updateUser({password:f.password});if(r.error)throw Error('Не удалось изменить пароль. Попробуй запросить новую ссылку.');account.recovery=false;notify();msg('Пароль обновлён.')}else{const r=await client.auth.signInWithPassword(f);if(r.error)throw Error('Не удалось войти. Проверь email и пароль, а также подтверждение email.');location.hash='courses'}})};
if($('#register'))$('#register').onclick=()=>{const f=fields();if(!f)return;run(async()=>{const r=await client.auth.signUp({...f,options:{emailRedirectTo:redirect}});if(r.error)throw Error('Регистрация не выполнена. Возможно, превышен лимит писем — попробуй позже.');if(r.data?.session){location.hash='start'}else if(account.emailConfirmationRequired){msg('Проверь почту: подтверди email по ссылке. Если аккаунт уже есть, используй вход или восстановление пароля.')}else{msg('Аккаунт уже может существовать. Попробуй войти с паролем.')}})};
if($('#password-reset'))$('#password-reset').onclick=()=>{const email=form.querySelector('[name=email]');if(!email.reportValidity())return;run(async()=>{const r=await client.auth.resetPasswordForEmail(email.value.trim(),{redirectTo:redirect});if(r.error)throw Error('Не удалось отправить ссылку. Попробуй позже.');msg('Если аккаунт существует, на почту придёт ссылка восстановления.')})};
if($('#logout'))$('#logout').onclick=()=>run(async()=>{await flush();if(pending||writing)throw Error('Есть несохранённый прогресс. Повтори сохранение перед выходом.');const r=await client.auth.signOut();if(r.error)throw Error('Не удалось выйти. Повтори попытку.');location.hash='account'});
if($('#cloud-retry'))$('#cloud-retry').onclick=()=>run(async()=>{if(conflict)throw Error('Сначала загрузи актуальную версию из базы.');await flush();msg(account.status)});
if($('#cloud-reload'))$('#cloud-reload').onclick=()=>{if(pending&&!confirm('Загрузить прогресс из базы? Несохранённые изменения на этом устройстве будут потеряны.'))return;account.ready=false;load(session)};
if($('#legacy-show'))$('#legacy-show').onclick=()=>{let legacy;try{legacy=JSON.parse(localStorage.getItem('bora.pilot.v1')||'{}')}catch{legacy={}}const box=$('#legacy-options');box.replaceChildren();for(const id of ['one','two']){const state=legacy[id];if(!state||typeof state!=='object')continue;const b=document.createElement('button');b.className='btn alt';b.style.marginTop='10px';b.textContent='Перенести '+(state.name||'Профиль '+(id==='one'?'1':'2'));b.onclick=()=>{const current=getState();if((revision>0||Object.keys(current.courseProgress||{}).length)&&!confirm('Заменить прогресс текущего аккаунта выбранным старым профилем?'))return;applyState(cleanState(state));account.queue(state);flush();msg('Перенос начат. Дождись сообщения «Сохранено в базе».')};box.append(b)}if(!box.childNodes.length)box.textContent='В этом браузере прежних профилей не найдено.'};
};
window.addEventListener('beforeunload',e=>{if(pending||writing){e.preventDefault();e.returnValue=''}});
window.addEventListener('online',()=>flush());
window.BoraAccount=account;
})();
